fun fuse(bm25: List<Hit>, vector: List<Hit>, k: Int = 60): List<Hit> {
    val scores = HashMap<String, Double>()
    bm25.forEach { hit ->
        scores.merge(hit.id, 1.0 / (k + hit.rank), Double::plus)
    }
    vector.withIndex().forEach { (i, hit) ->
        scores.merge(hit.id, 1.0 / (k + i), Double::plus)
    }
    return scores.entries
        .sortedByDescending { it.value }
        .map { (id, score) -> Hit(id, score) }
}

